CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE projects (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, locality text NOT NULL, publication_status text NOT NULL DEFAULT 'draft' CHECK(publication_status IN ('draft','published')), is_synthetic boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(organization_id,id));
CREATE TABLE users (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), keycloak_subject text UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','disabled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(organization_id,id));
CREATE TABLE channel_identities (id uuid PRIMARY KEY, organization_id uuid NOT NULL, user_id uuid NOT NULL, provider text NOT NULL CHECK(provider IN ('web','zalo')), provider_subject text NOT NULL, verified_at timestamptz, linked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, FOREIGN KEY(organization_id,user_id) REFERENCES users(organization_id,id), UNIQUE(provider,provider_subject));
CREATE TABLE prep_dossiers (id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, owner_user_id uuid NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','archived')), phase text NOT NULL DEFAULT 'preparation' CHECK(phase='preparation'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1 CHECK(version>0), FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id), FOREIGN KEY(organization_id,owner_user_id) REFERENCES users(organization_id,id), UNIQUE(organization_id,project_id,id));
-- PII payload must be authenticated ciphertext produced by a future key-managed encryption layer.
CREATE TABLE declaration_versions (id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, dossier_id uuid NOT NULL, schema_version text NOT NULL, encrypted_payload bytea NOT NULL, created_by uuid NOT NULL, source text NOT NULL CHECK(source IN ('citizen','human_confirmed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL CHECK(version>0), FOREIGN KEY(organization_id,project_id,dossier_id) REFERENCES prep_dossiers(organization_id,project_id,id), FOREIGN KEY(organization_id,created_by) REFERENCES users(organization_id,id), UNIQUE(dossier_id,version));
CREATE TABLE documents (id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, dossier_id uuid NOT NULL, object_key text NOT NULL UNIQUE, sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'), mime text NOT NULL, scan_status text NOT NULL DEFAULT 'quarantined' CHECK(scan_status IN ('quarantined','clean','rejected')), verification_status text NOT NULL DEFAULT 'unverified', retention_class text NOT NULL DEFAULT 'legal-review-required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, FOREIGN KEY(organization_id,project_id,dossier_id) REFERENCES prep_dossiers(organization_id,project_id,id));
CREATE TABLE consent_records (id uuid PRIMARY KEY, organization_id uuid NOT NULL, user_id uuid NOT NULL, purpose text NOT NULL, notice_version text NOT NULL, granted_at timestamptz NOT NULL, withdrawn_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, FOREIGN KEY(organization_id,user_id) REFERENCES users(organization_id,id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, actor_ref text NOT NULL, action text NOT NULL, resource_ref text NOT NULL, prev_hash text, event_hash text NOT NULL CHECK(event_hash ~ '^[a-f0-9]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id));
CREATE TABLE outbox_events (id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, event_type text NOT NULL, resource_ref text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered','failed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id));
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='noxh_runtime') THEN CREATE ROLE noxh_runtime NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
GRANT USAGE ON SCHEMA public TO noxh_runtime;
GRANT SELECT ON organizations, projects, users, channel_identities, prep_dossiers, declaration_versions, documents, consent_records, audit_events, outbox_events TO noxh_runtime;
GRANT INSERT, UPDATE ON prep_dossiers,documents,consent_records,outbox_events TO noxh_runtime;
GRANT INSERT ON declaration_versions,audit_events TO noxh_runtime;
-- Sprint 0 only owner policies. Staff policy integration is NOT implemented.
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY; ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY org_scope ON organizations FOR SELECT TO noxh_runtime USING(id::text=current_setting('app.organization_id',true));
ALTER TABLE projects ENABLE ROW LEVEL SECURITY; ALTER TABLE projects FORCE ROW LEVEL SECURITY;
CREATE POLICY project_scope ON projects FOR SELECT TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND id::text=current_setting('app.project_id',true));
ALTER TABLE users ENABLE ROW LEVEL SECURITY; ALTER TABLE users FORCE ROW LEVEL SECURITY;
CREATE POLICY user_owner ON users FOR SELECT TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND id::text=current_setting('app.user_id',true));
ALTER TABLE channel_identities ENABLE ROW LEVEL SECURITY; ALTER TABLE channel_identities FORCE ROW LEVEL SECURITY;
CREATE POLICY channel_owner ON channel_identities FOR SELECT TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND user_id::text=current_setting('app.user_id',true));
ALTER TABLE prep_dossiers ENABLE ROW LEVEL SECURITY; ALTER TABLE prep_dossiers FORCE ROW LEVEL SECURITY;
CREATE POLICY dossier_owner ON prep_dossiers TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND project_id::text=current_setting('app.project_id',true) AND owner_user_id::text=current_setting('app.user_id',true)) WITH CHECK(organization_id::text=current_setting('app.organization_id',true) AND project_id::text=current_setting('app.project_id',true) AND owner_user_id::text=current_setting('app.user_id',true));
ALTER TABLE declaration_versions ENABLE ROW LEVEL SECURITY; ALTER TABLE declaration_versions FORCE ROW LEVEL SECURITY;
CREATE POLICY declaration_owner ON declaration_versions TO noxh_runtime USING(EXISTS(SELECT 1 FROM prep_dossiers d WHERE d.id=dossier_id AND d.organization_id=declaration_versions.organization_id AND d.project_id=declaration_versions.project_id)) WITH CHECK(created_by::text=current_setting('app.user_id',true) AND EXISTS(SELECT 1 FROM prep_dossiers d WHERE d.id=dossier_id AND d.organization_id=declaration_versions.organization_id AND d.project_id=declaration_versions.project_id));
ALTER TABLE documents ENABLE ROW LEVEL SECURITY; ALTER TABLE documents FORCE ROW LEVEL SECURITY;
CREATE POLICY document_owner ON documents TO noxh_runtime USING(EXISTS(SELECT 1 FROM prep_dossiers d WHERE d.id=dossier_id AND d.organization_id=documents.organization_id AND d.project_id=documents.project_id)) WITH CHECK(EXISTS(SELECT 1 FROM prep_dossiers d WHERE d.id=dossier_id AND d.organization_id=documents.organization_id AND d.project_id=documents.project_id));
ALTER TABLE consent_records ENABLE ROW LEVEL SECURITY; ALTER TABLE consent_records FORCE ROW LEVEL SECURITY;
CREATE POLICY consent_owner ON consent_records TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND user_id::text=current_setting('app.user_id',true)) WITH CHECK(organization_id::text=current_setting('app.organization_id',true) AND user_id::text=current_setting('app.user_id',true));
-- No runtime audit/outbox policies yet: access stays denied until server actors are integrated.
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;
ALTER TABLE outbox_events ENABLE ROW LEVEL SECURITY; ALTER TABLE outbox_events FORCE ROW LEVEL SECURITY;
